333	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
334	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
335	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
336	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
337	     * {@code "+61412345678"}.
338	     *
339	     * @param telephone the raw telephone value from the request
340	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
341	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
342	     */
343	    private static String normalizeTelephone(String telephone) {
344	        String e164 = toE164(telephone);
345	        if (e164 == null) {
346	            throw new InvalidFieldValueException("telephone",
347	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
348	        }
349	        return e164;
