378	    /**
379	     * Checks the national-number length against the country code for the country codes that pin one.
380	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
381	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
382	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
383	     */
384	    private static boolean hasValidNationalLength(String digits) {
385	        if (digits.startsWith("61")) {
386	            return digits.length() - 2 == 9;
387	        }
388	        if (digits.startsWith("1")) {
389	            return digits.length() - 1 == 10;
390	        }
391	        return true;
392	    }
